---
.shell {
  display: grid;
  /* The sidebar column is fluid so it shrinks with the viewport — its own
     container query in Sidebar.module.css is what decides when that
     shrinking should also change its layout, not this rule. */
  grid-template-columns: clamp(3.5rem, 16vw, 15rem) 1fr;
  min-height: 100dvh;
}

.content {
  min-width: 0;
  padding: 2rem 2.5rem;
}
---BUTTON---
import type { ButtonHTMLAttributes, ReactNode } from "react";
import { cx } from "../../lib/class-names";
import css from "./Button.module.css";

type ButtonVariant = "primary" | "secondary" | "danger";

interface ButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  readonly children: ReactNode;
  readonly variant?: ButtonVariant;
  /** Disables the button and applies a busy affordance; caller supplies the label change ("Publishing…"). */
  readonly loading?: boolean;
  /** Marks the button's last action as having failed, without disabling it. */
  readonly error?: boolean;
  readonly className?: string;
}

export function Button({
  children,
  variant = "primary",
  loading = false,
  error = false,
  className,
  disabled,
  type = "button",
  ...rest
}: ButtonProps) {
  return (
    <button
      type={type}
      className={cx(css.button, css[variant], error && css.error, className)}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...rest}
    >
      {children}
    </button>
  );
}
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid transparent;
  border-radius: 0.375rem;
  padding: 0.5rem 1rem;
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.2;
  cursor: pointer;
  transition:
    background-color 120ms ease-out,
    border-color 120ms ease-out,
    opacity 120ms ease-out;
}

.primary {
  background: #1f2a44;
  color: #fff;
  border-color: #1f2a44;
}

.primary:hover:not(:disabled) {
  background: #16203a;
}

.secondary {
  background: #fff;
  color: #1f2a44;
  border-color: #c9cfdb;
}

.secondary:hover:not(:disabled) {
  background: #f2f4f8;
}

.danger {
  background: #a4302f;
  color: #fff;
  border-color: #a4302f;
}

.danger:hover:not(:disabled) {
  background: #872724;
}

.button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* Loading uses the same accessibility attribute as its styling hook, rather
   than a parallel `.loading` class the two could drift out of sync. No
   spinner keyframe here — the toast owns this app's one animation. */
.button[aria-busy="true"] {
  cursor: progress;
}

.error {
  border-color: #a4302f;
  box-shadow: 0 0 0 1px #a4302f inset;
}

